\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:39:\"Blog – WordPress.org English (Canada)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:27:\"https://en-ca.wordpress.org\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"width\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"height\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:73:\"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"The final countdown to WordCamp Canada 2025\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://en-ca.wordpress.org/2025/09/17/the-final-countdown-to-wordcamp-canada-2025/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://en-ca.wordpress.org/2025/09/17/the-final-countdown-to-wordcamp-canada-2025/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 17 Sep 2025 20:00:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=727\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:314:\"We are less than a month away from the opening of WordCamp Canada 2025 at Carleton University in Ottawa, Ontario from October 15 to 17. Get your tickets now while they are still available. Plan for a special Contributor Day Now is a great time to plan your trip. Area hotel discounts are still available. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dan Knauss\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2335:\"\n<p class=\"wp-block-paragraph\">We are less than a month away from the opening of WordCamp Canada 2025 at Carleton University in Ottawa, Ontario from October 15 to 17. <a href=\"https://canada.wordcamp.org/2025/tickets/\">Get your tickets now</a> while they are still available.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Plan for a special Contributor Day</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Now is a great time to <a href=\"https://canada.wordcamp.org/2025/plan-your-trip-to-wordcamp-canada-2025/\">plan your trip</a>. Area hotel discounts are still available. If you attend <a href=\"https://canada.wordcamp.org/2025/contributor-day-is-back-at-wordcamp-canada-with-two-surprises/\">Contributor Day</a> on the 15th, you&#8217;ll be able to join <a href=\"https://canada.wordcamp.org/2025/a-whole-new-day-of-workshops-is-coming-to-wordcamp-canada/\">some unique and special workshops</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Get to know our speakers</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Get acquainted with our <a href=\"https://canada.wordcamp.org/2025/speakers/\">Speakers</a>, <a href=\"https://canada.wordcamp.org/2025/sponsors/\">Sponsors</a>, and Keynotes: <a href=\"https://www.google.com/url?q=https://canada.wordcamp.org/2025/wceh-keynote-dave-winer/&amp;sa=D&amp;source=editors&amp;ust=1757148172761006&amp;usg=AOvVaw2X49AxeTalbX7cZyYvZrib\">Dave Winer</a>, <a href=\"https://www.google.com/url?q=https://canada.wordcamp.org/2025/wceh-keynote-evan-prodromou/&amp;sa=D&amp;source=editors&amp;ust=1757148172761314&amp;usg=AOvVaw3BAO8WCDbEJWLmRzX-xAXU\">Evan Prodromou</a>, and <a href=\"https://www.google.com/url?q=https://canada.wordcamp.org/2025/speaker/jill-binder/&amp;sa=D&amp;source=editors&amp;ust=1757148172761623&amp;usg=AOvVaw2pSGmnTvMH_KfZm1EtV-0r\">Jill Binder</a>. You can view the <a href=\"https://canada.wordcamp.org/2025/schedule/\">full schedule</a> and <a href=\"https://canada.wordcamp.org/2025/sessions/\">individual sessions</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Connect with the Canadian WordPress community</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Meet other attendees in advance on <a href=\"https://wp-ca.slack.com/\">WP Canada Slack</a> in the <a href=\"https://wp-ca.slack.com/archives/C7BHZL7M3\">#wccanada</a> channel.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re looking forward to seeing you in Ottawa!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://en-ca.wordpress.org/2025/09/17/the-final-countdown-to-wordcamp-canada-2025/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"727\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:88:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n		\n		\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"Speakers confirmed for WordCamp Canada #WCEH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://en-ca.wordpress.org/2025/08/03/speakers-confirmed-for-wordcamp-canada/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://en-ca.wordpress.org/2025/08/03/speakers-confirmed-for-wordcamp-canada/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 03 Aug 2025 23:54:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:6:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:2;a:5:{s:4:\"data\";s:19:\"Carleton University\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:3;a:5:{s:4:\"data\";s:16:\"English (Canada)\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:4;a:5:{s:4:\"data\";s:15:\"WordCamp Canada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:5;a:5:{s:4:\"data\";s:9:\"WordPress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=719\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:400:\"WordPress enthusiasts, developers, business owners, and content creators from across Canada and around the world will converge at Carleton University this fall for WordCamp Canada 2025 (WCEH25), taking place October 16–17, 2025. This national flagship event brings together the open web community for two days of learning, networking, and inspiration focused on WordPress, the open-source [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dan Knauss\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4901:\"\n<p class=\"wp-block-paragraph\">WordPress enthusiasts, developers, business owners, and content creators from across Canada and around the world will converge at <strong>Carleton University</strong> this fall for <strong><a href=\"https://canada.wordcamp.org/2025/\">WordCamp Canada 2025</a></strong> (WCEH25), taking place <strong>October 16–17, 2025</strong>. </p>\n\n\n\n<p class=\"wp-block-paragraph\">This national flagship event brings together the <strong>open web community</strong> for two days of learning, networking, and inspiration focused on <strong>WordPress</strong>, the open-source platform powering nearly half the web.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Keynotes Will Take on the Future of the Open Web</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WCEH25 will feature two keynote talks that will frame some of the most important conversations happening around WordPress and the open web.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><a href=\"https://canada.wordcamp.org/2025/wceh-keynote-dave-winer/\">Dave Winer</a></strong>, the pioneering developer and writer whose work helped shape blogging, RSS, and podcasting, will present <a href=\"https://canada.wordcamp.org/2025/session/wordpress-and-the-open-social-web/\"><em>WordPress and the Open Social Web</em></a>. He’ll share lessons from decades of building for the open internet and make the case for WordPress as a cornerstone of a more distributed, user-owned web.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong><a href=\"https://canada.wordcamp.org/2025/wceh-keynote-evan-prodromou/\">Evan Prodromou</a></strong>, founder of identi.ca and long-time advocate for open standards and federation, will deliver <a href=\"https://canada.wordcamp.org/2025/session/beyond-microblogging-wordpress-leads-the-way-in-long-form-text-on-the-social-web/\"><em>Beyond Microblogging: WordPress Leads the Way in Long-Form Text on the Social Web</em></a>. His talk explores how WordPress is uniquely positioned to support rich, thoughtful publishing in a social web increasingly dominated by brevity and walled gardens.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Together, these keynotes will set the tone for discussion, reflection, and hands-on learning, rooted in the idea that WordPress doesn’t just power websites, it helps shape the future of the web itself.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Speakers With Diverse Perspectives to Lead Deep Dives on Key Subjects</h2>\n\n\n\n<p class=\"wp-block-paragraph\">At this time, more than a dozen names and topics have been confirmed for the <a href=\"https://canada.wordcamp.org/2025/announcing-our-first-speakers-for-wordcamp-canada-2025/\">first group of speakers</a> who will give presentations and lead workshops at WCEH25. These speakers will take on a wide range of topics from accessibility, performance, and publishing workflows to block development, design systems, and community sustainability. They span a breadth of perspectives that, together, give the WordPress community its outsized impact on the evolution of the publishing and business. </p>\n\n\n\n<p class=\"wp-block-paragraph\">“WordCamp Canada is about more than just websites,” says James Giroux, lead organizer for WCEH25. “It’s about <strong>building a web that’s more open, ethical, and inclusive</strong> — and that starts with bringing people together from every part of the ecosystem.”</p>\n\n\n\n<h2 class=\"wp-block-heading\">Tickets and Travel Planning</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Tickets for WordCamp Canada are on sale now <a href=\"https://canada.wordcamp.org/2025/tickets/\">at the WCEH25 website</a>. For a limited time, <a href=\"https://canada.wordcamp.org/2025/hotel-recommendations/\">several area hotels are offering discounted rates for WCEH attendees</a>. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Organizers have shared <a href=\"https://canada.wordcamp.org/2025/plan-your-trip-to-wordcamp-canada-2025/\">a travel planning guide</a> for those travelling to Ottawa internationally and from all over Canada. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Plan your trip today, and join the WordPress community in Ontario in October! </p>\n\n\n\n<figure class=\"wp-block-embed is-type-wp-embed is-provider-wordcamp-canada-2025 wp-block-embed-wordcamp-canada-2025\"><div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"wp-embedded-content\" data-secret=\"EL24q05mDV\"><a href=\"https://canada.wordcamp.org/2025/plan-your-trip-to-wordcamp-canada-2025/\">Plan Your Trip to WordCamp Canada 2025</a></blockquote><iframe class=\"wp-embedded-content\" sandbox=\"allow-scripts\" security=\"restricted\"  title=\"&#8220;Plan Your Trip to WordCamp Canada 2025&#8221; &#8212; WordCamp Canada 2025\" src=\"https://canada.wordcamp.org/2025/plan-your-trip-to-wordcamp-canada-2025/embed/#?secret=ognD9vgUaY#?secret=EL24q05mDV\" data-secret=\"EL24q05mDV\" width=\"500\" height=\"282\" frameborder=\"0\" marginwidth=\"0\" marginheight=\"0\" scrolling=\"no\"></iframe>\n</div></figure>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://en-ca.wordpress.org/2025/08/03/speakers-confirmed-for-wordcamp-canada/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"719\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"WordCamp Canada 2025 Call for Speakers #WCEH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://en-ca.wordpress.org/2025/04/28/wordcamp-canada-2025-call-for-speakers-wceh/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://en-ca.wordpress.org/2025/04/28/wordcamp-canada-2025-call-for-speakers-wceh/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 28 Apr 2025 05:56:42 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"WordCamp Canada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=655\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:106:\"WCEH\'s Call for Speakers is open until June 15. Ready to inspire and be inspired? \nApply to Speak at WCEH!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dan Knauss\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2490:\"\n<h2 class=\"wp-block-heading\">WCEH&#8217;s Call for Speakers is open until June 15.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">When the leaves turn, do you ever think about the days you used to head back to school? The crackle of new ideas and energy, the excitement of seeing new faces and old friends?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Remember that insatiable sense of possibility, where curiosity ruled, and no challenge was too big?&nbsp;</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re returning to campus at Carleton University in Ottawa, Ontario from October 16-17, 2025 — and we want to showcase speakers who engage with topics like:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>The Future of WordPress in an AI-Driven World.</strong></li>\n\n\n\n<li><strong>Keeping the Web Open in the Age of Closed Platforms.</strong>&nbsp;</li>\n\n\n\n<li><strong>Pushing the Boundaries of Innovation.</strong></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Learn more in the <strong><a href=\"https://canada.wordcamp.org/2025/this-fall-speak-at-wordcamp-canada/\">Call for Speakers</a></strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Timeline</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>April 23 to June 15, 2025 — Call For Speakers is Open</strong></li>\n\n\n\n<li>June 15 to July 20, 2025 — Speakers selection</li>\n\n\n\n<li>July 20 to August 15, 2025 — Applicant notifications</li>\n\n\n\n<li>August 15 to September 5, 2025 — Schedule release/speakers lineup announcement</li>\n\n\n\n<li>September 30, 2025 — Delivery deadline for slides</li>\n\n\n\n<li><strong>October 16-17, 2025 — WordCamp Canada</strong></li>\n</ul>\n\n\n\n<div style=\"height:var(--wp--preset--spacing--10)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n\n\n\n<div class=\"wp-block-group is-layout-constrained wp-block-group-is-layout-constrained\" style=\"border-width:1px\">\n<h2 class=\"wp-block-heading has-text-align-center is-style-default\">Ready to inspire and be inspired? </h2>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-b4f207a3 wp-block-buttons-is-layout-flex\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"https://canada.wordcamp.org/2025/this-fall-speak-at-wordcamp-canada/#speaker-application\">Apply to Speak at WCEH <span aria-hidden=\"true\" class=\"wp-exclude-emoji\">→</span></a></div>\n</div>\n</div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://en-ca.wordpress.org/2025/04/28/wordcamp-canada-2025-call-for-speakers-wceh/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"655\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:73:\"\n		\n		\n					\n		\n		\n		\n				\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"WordCamp Canada 2025 Call for Volunteers #WCEH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://en-ca.wordpress.org/2025/04/03/wordcamp-canada-2025-call-for-volunteers-wceh/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://en-ca.wordpress.org/2025/04/03/wordcamp-canada-2025-call-for-volunteers-wceh/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 03 Apr 2025 20:06:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=644\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:371:\"Like the WordPress software project WordCamp Canada (WCEH) is an open source event. It’s planned, organized, and run by the Canadian WordPress community with volunteers and attendees welcomed from all over the world.&#160; To gather our full team for WCEH 2025, we&#8217;ve issued a Call for Volunteers. Volunteer Responsibilities and Benefits If you join the [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dan Knauss\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:1870:\"\n<p class=\"wp-block-paragraph\">Like the WordPress software project WordCamp Canada (WCEH) is an open source event. It’s planned, organized, and run by the Canadian WordPress community with volunteers and attendees welcomed from all over the world.&nbsp;</p>\n\n\n\n<p class=\"wp-block-paragraph\">To gather our full team for WCEH 2025, we&#8217;ve issued a <a href=\"https://canada.wordcamp.org/2025/call-for-volunteers/\">Call for Volunteers</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Volunteer Responsibilities and Benefits</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you join the WCEH25 team, you will be needed to work throughout WordCamp Canada over the two days it takes place at Carleton. You can help prior to the event too! Most teams are actively engaged in planning and tasks that must be completed well in advance of the event.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>All volunteers will get free admission and an event t-shirt.</li>\n</ul>\n\n\n\n<ul class=\"wp-block-list\">\n<li>All volunteers must be familiar with and follow the&nbsp;<a href=\"https://make.wordpress.org/handbook/community-code-of-conduct/\">Community Code of Conduct</a>.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>We’d love to have you join us</strong> this year at <strong>Carleton University</strong> in <strong>Ottawa, Ontario</strong> from <strong>October 16-17</strong>.</p>\n\n\n\n<h2 class=\"wp-block-heading has-text-align-center\">Join Team WCEH</h2>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-36078703 wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://canada.wordcamp.org/2025/call-for-volunteers/\">Apply to Volunteer <span aria-hidden=\"true\" class=\"wp-exclude-emoji\">→</span></a></div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\"><br><br></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://en-ca.wordpress.org/2025/04/03/wordcamp-canada-2025-call-for-volunteers-wceh/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"644\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"WordCamp Canada 2025 Call for Sponsors #WCEH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://en-ca.wordpress.org/2025/03/20/wordcamp-canada-2025-call-for-sponsors-wceh/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://en-ca.wordpress.org/2025/03/20/wordcamp-canada-2025-call-for-sponsors-wceh/#comments\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 20 Mar 2025 20:15:43 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:15:\"WordCamp Canada\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=633\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:166:\"The WordCamp Canada 2025 (WCEH) organizing team has issued a Call for Sponsors. A prospectus outlining the sponsorship packages is available on the WCEH 2025 website.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dan Knauss\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2528:\"\n<p class=\"wp-block-paragraph\">The <strong><a href=\"https://canada.wordcamp.org/2025/\">WordCamp Canada 2025</a></strong> (WCEH) organizing team has issued a <a href=\"https://canada.wordcamp.org/2025/call-for-sponsors/\">Call for Sponsors</a>. A <a href=\"https://canada.wordcamp.org/2025/sponsorship-prospectus/\">prospectus outlining the sponsorship packages</a> is now available on the WCEH 2025 website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This year, WordCamp Canada will take place from&nbsp;<strong>October 16-17</strong>&nbsp;in Carleton University’s <a href=\"https://conferenceservices.carleton.ca/cu-facilities/richcraft-hall/\">Richcraft Hall Atrium and Conference Centre</a>. This beautiful, highly accessible venue overlooks the Rideau River in Ottawa, Ontario. It&#8217;s just minutes from <a href=\"https://visit.parl.ca/sites/Visit/default/en_CA\">Parliament Hill</a>, <a href=\"https://www.byward-market.com/\">ByWard Market</a>, and the downtown riverfront.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What sets WCEH apart is its national scale—a rarity in the WordCamp ecosystem. Most WordCamps are regional or city-based, making WCEH one of very few national WordCamps in the world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sponsoring WordCamp Canada is a great way to support the WordPress community in Canada and as a whole. It&#8217;s also an excellent way to go beyond brand placement and become part of the WordPress community experience. WordCamp sponsors have a unique opportunity to forge meaningful relationships with their target audiences.</p>\n\n\n\n<h2 class=\"wp-block-heading has-text-align-center\">Support Team WCEH</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Learn more about WordCamp Canada, the location, and the venue on <a href=\"https://canada.wordcamp.org/2025/\">the WCEH 2025 website</a>. </li>\n\n\n\n<li>Contact&nbsp;<a href=\"mailto:canada@wordcamp.org\">canada@wordcamp.org</a>&nbsp;to discuss sponsorship options.</li>\n\n\n\n<li>Review&nbsp;<a href=\"https://canada.wordcamp.org/2025/sponsorship-prospectus/\">the sponsorship prospectus</a>&nbsp;and&nbsp;<a href=\"https://canada.wordcamp.org/2025/sponsorship-prospectus/#readytosponsor\">submit your application</a>.</li>\n</ul>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-36078703 wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Sponsor WordCamp Canada <span aria-hidden=\"true\" class=\"wp-exclude-emoji\">→</span></a></div>\n</div>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"https://en-ca.wordpress.org/2025/03/20/wordcamp-canada-2025-call-for-sponsors-wceh/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"633\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:76:\"\n		\n		\n					\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n					\n			\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:6:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"WordCamp Canada 2024 speaker schedule now available!  #WCEH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"https://en-ca.wordpress.org/2024/04/25/wordcamp-canada-2024-speaker-schedule-now-available-wceh/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:104:\"https://en-ca.wordpress.org/2024/04/25/wordcamp-canada-2024-speaker-schedule-now-available-wceh/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 26 Apr 2024 01:15:11 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:4:\"News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:9:\"community\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://en-ca.wordpress.org/?p=603\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:449:\"Our speaker schedule is now available, please see:&#160;https://canada.wordcamp.org/2024/schedule/ Regular tickets for WordCamp Canada 2024 are only $75 for 3 days of unforgettable learning, networking, and fun.  https://canada.wordcamp.org/2024/tickets/Connect with a community of like-minded individuals who share your passion for all things WordPress &#8211; July 11 to 13, 2024, in Ottawa. Call for Sponsors:To make WordCamp Canada a [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Paul Bearne\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2223:\"\n<p class=\"wp-block-paragraph\">Our speaker schedule is now available, please see:&nbsp;<a target=\"_blank\" href=\"https://canada.wordcamp.org/2024/schedule/\" rel=\"noreferrer noopener\">https://canada.wordcamp.org/2024/schedule/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Regular tickets for WordCamp Canada 2024 are only $75 for 3 days of unforgettable learning, networking, and fun.  <a href=\"https://canada.wordcamp.org/2024/tickets/\" target=\"_blank\" rel=\"noreferrer noopener\">https://canada.wordcamp.org/2024/tickets/</a><br>Connect with a community of like-minded individuals who share your passion for all things WordPress &#8211; July 11 to 13, 2024, in Ottawa.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Call for Sponsors:<br>To make WordCamp Canada a success, we are relying on the generous support of sponsors to cover a major part of the costs. By becoming a sponsor you will gain exposure to a highly targeted audience and demonstrate your commitment to the WordPress community. We have an outstanding lineup of speakers that has just been announced that is sure to attract a full crowd. Now we need the support of sponsors to make this exciting and ground-breaking event happen!  With sponsorship levels from Butter Tart and Poutine to Maple Syrup, we have tried to be imaginative in providing a range of opportunities and cost levels. Please see <a href=\"https://canada.wordcamp.org/2024/sponsorship-prospectus/\" target=\"_blank\" rel=\"noreferrer noopener\">https://canada.wordcamp.org/2024/sponsorship-prospectus/</a> for details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Call for Volunteers:<br>There is an endless list of tasks to do to make a WordCamp happen.&nbsp; We&#8217;re looking for volunteers, both before and during the event. To volunteer to help out please see&nbsp;<a target=\"_blank\" href=\"https://canada.wordcamp.org/2024/call-for-volunteers/\" rel=\"noreferrer noopener\">https://canada.wordcamp.org/2024/call-for-volunteers/</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">We are also looking for translators for the website content. If you can help translate, or know someone who might be able to help us, please let us know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you,<br>WordCamp Canada 2024 Organizers</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"https://en-ca.wordpress.org/2024/04/25/wordcamp-canada-2024-speaker-schedule-now-available-wceh/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"603\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8: